/* v2.70 adaptive streaming in MPPlayer, in a real Chromium (no native HLS, MediaSource present) with the production CSP:
 *  · an HLS master (generated by ffmpeg: testsrc → master + 2 rungs, fMP4) plays through hls.js, fetched as the lazy «hls»
 *    chunk (never part of the core bundle); playback passes currentTime 0.5 with both quality levels known to hls.js
 *  · MPPlayer.destroy(el) pauses, detaches hls.js and clears the source (no src attribute, readyState 0)
 *  · a broken master is a fatal hls.js error → the MP4/WebM chain plays instead (no error box)
 *  · the preload option is passed through to the <video> element
 * The fixture is served under the test stack's own origin (/e2e-hls/*) by the browser context. */
const test = require("node:test"), assert = require("node:assert");
const fs = require("node:fs"), os = require("node:os"), path = require("node:path"), { execFileSync } = require("node:child_process");
const { startStack, ensureBuild, MOBILE } = require("./harness");
const FX = fs.mkdtempSync(path.join(os.tmpdir(), "abr270-"));
const ff = (...a) => execFileSync("ffmpeg", ["-hide_banner", "-loglevel", "error", "-y", ...a], { cwd: FX });
const TYPES = { ".m3u8": "application/vnd.apple.mpegurl", ".m4s": "video/iso.segment", ".mp4": "video/mp4", ".webm": "video/webm" };
let S; const errors = [], chunkReqs = [];
/** poll a page function (page.waitForFunction evaluates strings, which the real CSP refuses) */
const until = async (p, fn, arg, ms = 30000) => { const end = Date.now() + ms; for (;;) { if (await p.evaluate(fn, arg).catch(() => false)) return; if (Date.now() > end) throw new Error("timed out: " + fn.toString().slice(0, 120)); await new Promise((r) => setTimeout(r, 150)); } };

test.before(async () => {
  // Chromium here has no H.264, so the ladder is VP9 in fMP4 (the player code path is codec-agnostic)
  for (const [w, h, br] of [[426, 240, 300], [640, 360, 600]]) {
    ff("-f", "lavfi", "-i", `testsrc=size=${w}x${h}:rate=24`, "-t", "4", "-c:v", "libvpx-vp9", "-b:v", br + "k", "-deadline", "realtime", "-cpu-used", "8", "-g", "24", "-pix_fmt", "yuv420p",
      "-f", "hls", "-hls_time", "1", "-hls_playlist_type", "vod", "-hls_segment_type", "fmp4", "-hls_fmp4_init_filename", `i${h}.mp4`, "-hls_segment_filename", `s${h}_%03d.m4s`, `v${h}.m3u8`);
  }
  fs.writeFileSync(path.join(FX, "master.m3u8"), "#EXTM3U\n#EXT-X-VERSION:7\n" +
    '#EXT-X-STREAM-INF:BANDWIDTH=350000,RESOLUTION=426x240,CODECS="vp09.00.10.08"\nv240.m3u8\n' +
    '#EXT-X-STREAM-INF:BANDWIDTH=700000,RESOLUTION=640x360,CODECS="vp09.00.10.08"\nv360.m3u8\n');
  fs.writeFileSync(path.join(FX, "broken.m3u8"), "this is not a playlist");
  ff("-f", "lavfi", "-i", "testsrc=size=320x180:rate=24", "-t", "3", "-c:v", "libvpx", "-b:v", "200k", "fallback.webm");
  ensureBuild();
  S = await startStack();
});
test.after(async () => { await S?.close(); assert.deepEqual(errors, [], "no uncaught page errors"); });

async function open() {
  const c = await S.browser.newContext({ ...MOBILE, bypassCSP: false }); // the real CSP (media-src blob:, no blob: workers)
  await c.route("https://sdk.minepi.com/**", (r) => r.fulfill({ status: 200, contentType: "text/javascript", body: "" }));
  await c.route(S.base + "/e2e-hls/**", (r) => {
    const f = path.join(FX, path.basename(new URL(r.request().url()).pathname));
    if (!fs.existsSync(f)) return r.fulfill({ status: 404, body: "" });
    return r.fulfill({ status: 200, contentType: TYPES[path.extname(f)] || "application/octet-stream", body: fs.readFileSync(f) });
  });
  const p = await c.newPage();
  p.on("pageerror", (e) => errors.push(e.message));
  p.on("request", (q) => { if (/\/assets\/chunk-hls-/.test(q.url())) chunkReqs.push(q.url()); });
  await p.goto(S.base + "/?nosw");
  await until(p, () => !!(window.MPPlayer && window.MPChunks), null, 20000);
  return p;
}
/** mount a player on a fresh box with the given variants and options */
const mount = (p, variants, opts) => p.evaluate(([vr, o]) => {
  document.getElementById("abr")?.remove();
  const el = document.createElement("div"); el.id = "abr"; el.className = "mp-video"; el.style.width = "360px"; document.body.prepend(el);
  window.MPPlayer.mount(el, { id: "abr", video: { duration: 4, variants: vr } }, o); return true;
}, [variants, opts]);

test("HLS master plays through the lazy hls.js chunk (auto quality), destroy() frees the source", async () => {
  const p = await open();
  assert.equal(await p.evaluate(() => !!window.Hls), false, "hls.js is not in the core bundle");
  assert.equal(await p.evaluate(() => document.createElement("video").canPlayType("application/vnd.apple.mpegurl")), "", "no native HLS in this browser");
  await mount(p, { master: "/e2e-hls/master.m3u8", "360p": "/e2e-hls/fallback.webm" }, { autoplay: true, muted: true, preload: "auto" });
  await until(p, () => { const el = document.getElementById("abr"), v = el.querySelector("video"); return !!el._mpHls && v.currentTime > 0.5; });
  const s = await p.evaluate(() => { const el = document.getElementById("abr"), v = el.querySelector("video"), h = el._mpHls;
    return { hls: !!window.Hls, levels: h.levels.length, cap: h.config.capLevelToPlayerSize, start: h.config.startLevel, buf: h.config.maxBufferLength, blob: v.currentSrc.startsWith("blob:"), preload: v.getAttribute("preload"), err: !el.querySelector(".mp-err").hidden, list: el._mpSources }; });
  assert.ok(s.hls && chunkReqs.length >= 1, "hls.js arrived as the lazy chunk");
  assert.equal(s.levels, 2, "both rungs of the ladder are known"); assert.equal(s.cap, true); assert.equal(s.start, -1); assert.equal(s.buf, 10);
  assert.ok(s.blob, "MediaSource playback"); assert.equal(s.preload, "auto"); assert.equal(s.err, false);
  assert.deepEqual(s.list, ["/e2e-hls/master.m3u8", "/e2e-hls/fallback.webm"], "fallback chain kept after the master");
  const d = await p.evaluate(() => { const el = document.getElementById("abr"), v = el.querySelector("video"); window.MPPlayer.destroy(el);
    return { src: v.hasAttribute("src"), net: v.networkState, ready: v.readyState, paused: v.paused, hls: el._mpHls, mounted: el.classList.contains("mounted") }; });
  assert.equal(d.src, false, "src attribute removed"); assert.ok(d.net === 0 || d.net === 3, "NETWORK_EMPTY/NO_SOURCE: nothing is fetched any more (" + d.net + ")"); assert.equal(d.ready, 0, "decoder released"); assert.equal(d.paused, true); assert.equal(d.hls, null, "hls.js detached"); assert.equal(d.mounted, false, "the box can be mounted again");
  await p.waitForTimeout(400);
  assert.equal(await p.evaluate(() => document.querySelector("#abr .mp-err").hidden), true, "destroy never shows the error box");
  await p.context().close();
});

test("a fatal hls.js error falls back to the MP4/WebM chain; preload passes through", async () => {
  const p = await open();
  await mount(p, { master: "/e2e-hls/broken.m3u8", "360p": "/e2e-hls/fallback.webm" }, { autoplay: true, muted: true });
  await until(p, () => { const v = document.querySelector("#abr video"); return /fallback\.webm$/.test(v.currentSrc) && v.currentTime > 0.3; });
  assert.equal(await p.evaluate(() => [document.getElementById("abr")._mpHls ?? null, document.querySelector("#abr .mp-err").hidden, document.querySelector("#abr video").getAttribute("preload")].map(String).join("|")), "null|true|metadata", "fallback plays, default preload=metadata");
  await mount(p, { master: "/e2e-hls/master.m3u8" }, { preload: "none" });
  assert.equal(await p.evaluate(() => document.querySelector("#abr video").getAttribute("preload")), "none");
  await p.waitForTimeout(800);
  assert.equal(await p.evaluate(() => document.querySelector("#abr video").readyState), 0, "preload none: nothing buffered before play");
  await p.evaluate(() => window.MPPlayer.destroy(document.getElementById("abr")));
  await p.context().close();
});
